WITH t AS (SELECT id, entity_name FROM project_plan_tasks WHERE project_id = $1 AND kind = 'dev'), need(title) AS (VALUES ('Что делать'),('Признак готовности'),('Чем доказывается'),('Что меняется в дереве')) SELECT t.id || ' — нет раздела «' || need.title || '»' AS detail FROM t CROSS JOIN need WHERE NOT EXISTS (SELECT 1 FROM project_document_sections s WHERE s.project_id = $1 AND s.entity_kind = 'task' AND s.entity_name = t.entity_name AND s.title = need.title) UNION ALL SELECT t.id || ' — нет ни «Где обычно ошибаются», ни «Что считается провалом»' FROM t WHERE NOT EXISTS (SELECT 1 FROM project_document_sections s WHERE s.project_id = $1 AND s.entity_kind = 'task' AND s.entity_name = t.entity_name AND s.title IN ('Где обычно ошибаются','Что считается провалом')) ORDER BY 1
